'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',configuration:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',players:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',mods:'M9 3H3v6h3a3 3 0 1 1 0 6H3v6h6v-3a3 3 0 1 1 6 0v3h6v-6h-3a3 3 0 1 1 0-6h3V3h-6v3a3 3 0 1 1-6 0z',clusters:'M9 2h6v6H9z M2 16h6v6H2z M16 16h6v6h-6z M12 8v5 M5 16v-3h14v3',backups:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',templates:'M8 3h10l3 3v14H8z M3 7v15h13 M17 3v5h4 M11 12h7 M11 16h5',discord:'M21 11a8 8 0 0 1-8 8H6l-4 3V11a9 9 0 0 1 18 0z M7 11h.01 M12 11h.01 M17 11h.01',console:'M4 5l6 7-6 7 M13 19h7',activity:'M2 12h5l3-8 4 16 3-8h5',preferences:'M4 5h16 M4 12h16 M4 19h16 M8 2v6 M16 9v6 M10 16v6',plus:'M12 5v14 M5 12h14',import:'M12 3v12 M7 10l5 5 5-5 M3 15v6h18v-6',play:'M7 3l14 9-14 9z',stop:'M5 5h14v14H5z',restart:'M3 11a9 9 0 1 1 3 8 M3 3v8h8',folder:'M3 5h7l2 3h9v13H3z',refresh:'M20 7a9 9 0 1 0 1 9 M20 2v5h-5',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',moon:'M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12z',link:'M10 13a5 5 0 0 0 7 0l4-4a5 5 0 0 0-7-7l-3 3 M14 11a5 5 0 0 0-7 0l-4 4a5 5 0 0 0 7 7l3-3',server:'M3 3h18v7H3z M3 14h18v7H3z M7 6h.01 M7 17h.01 M11 6h6 M11 17h6',chevron:'M9 5l7 7-7 7',save:'M4 3h14l3 3v15H3V3z M7 3v6h10V3 M7 21v-8h10v8',copy:'M8 8h13v13H8z M16 3H3v13',download:'M12 3v12 M7 10l5 5 5-5 M3 17v4h18v-4',trash:'M3 6h18 M5 6l1 15h12l1-15 M9 6V3h6v3 M10 10v7 M14 10v7'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.server}"/></svg>`;
const btn=(action,label,ico='',klass='',attrs='')=>`<button type="button" data-action="${action}" class="${klass}" ${attrs}>${ico?icon(ico):''}${h(label)}</button>`;
const field=(name,label,value='',type='text',attrs='')=>`<label>${h(label)}<input name="${name}" type="${type}" value="${h(value)}" ${attrs}></label>`;
const browseField=(name,label,value='',kind='folder')=>`<label>${h(label)}<span class="field-row"><input name="${name}" value="${h(value)}" required>${btn('browse',t('choose'),'folder','',`data-target="${name}" data-kind="${kind}"`)}</span></label>`;
const check=(name,label,value=false,attrs='')=>`<label class="check"><input type="checkbox" name="${name}" ${value?'checked':''} ${attrs}>${h(label)}</label>`;
const select=(name,label,options,value)=>`<label>${h(label)}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${h(v)}" ${v===value?'selected':''}>${h(l)}</option>`;}).join('')}</select></label>`;
let state,selected='',view='servers',configTab='basics',configs=null,configServer='',file='GameUserSettings.ini',dirty=false,toastTimer,busy=false;
const api=(method,data)=>window.asa.invoke(method,data);
const server=()=>state?.servers.find(s=>s.id===selected);
const date=v=>v?new Date(v).toLocaleString(window.currentLanguage==='zh'?'zh-CN':window.currentLanguage):'—';
const bytes=n=>n>1073741824?(n/1073741824).toFixed(2)+' GB':(n/1048576).toFixed(1)+' MB';
const status=s=>`<span class="badge ${s.status==='running'?'good':s.status==='stopped'?'':'busy'}"><span class="dot ${s.status==='running'?'green':s.status==='stopped'?'':'purple'}"></span>${h(t(s.status))}</span>`;
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className=error?'error':'';el.style.display='block';toastTimer=setTimeout(()=>el.style.display='none',error?12000:5000);}
async function load(){state=await api('snapshot');window.currentLanguage=state.settings.language;if(!state.servers.some(s=>s.id===selected))selected=state.servers[0]?.id||'';document.documentElement.lang=currentLanguage;document.body.className=state.settings.theme==='light'?'light':'';}
function shell(){const s=server(),nav=['servers','overview','configuration','players','mods','clusters','backups','templates','discord','console','activity'];return `<aside><div class="brand"><img class="brand-logo" src="../../assets/emblem.svg" alt=""><div><strong>ASA Chispi</strong><small>SERVER MANAGER</small></div></div><div class="aside-label">${h(t('fleet'))}</div><select class="server-picker" id="server-picker" aria-label="${h(t('fleet'))}">${state.servers.length?state.servers.map(s=>`<option value="${s.id}" ${s.id===selected?'selected':''}>${h(s.name)}</option>`).join(''):`<option>${h(t('noItems'))}</option>`}</select><div class="row">${btn('new',t('newServer'),'plus','small primary')}${btn('import',t('import'),'import','small')}</div><nav class="nav">${nav.map(n=>`<button data-action="nav" data-view="${n}" class="${view===n?'active':''}">${icon(n)}<span>${h(t(n))}</span>${n==='players'&&s?.playerCount!=null?`<span class="count">${s.playerCount}</span>`:''}</button>`).join('')}</nav><div class="aside-bottom"><nav class="nav">${btn('nav',t('preferences'),'preferences',view==='preferences'?'active':'','data-view="preferences"')}</nav><div class="host-status"><span class="dot purple"></span>${h(t('local'))}</div><div class="copyright">ASA Chispi Manager · 1.0.7<br>Made with ChatGPT / Codex</div></div></aside><main><header class="topbar"><div class="breadcrumb">${icon('server')}<span>${h(s?.name||'ASA Chispi Manager')}</span>${icon('chevron')}<span>${h(t(view))}</span></div><div class="top-actions"><select id="language-select" aria-label="${h(t('language'))}">${Object.entries(LANGS).map(([k,v])=>`<option value="${k}" ${k===currentLanguage?'selected':''}>${v}</option>`).join('')}</select>${btn('theme','',state.settings.theme==='dark'?'sun':'moon','icon',`aria-label="${h(t('theme'))}" title="${h(t('theme'))}"`)}${btn('refresh','', 'refresh','icon',`aria-label="${h(t('refresh'))}" title="${h(t('refresh'))}"`)}</div></header><div id="page">${page()}</div></main>`;}
function heading(title,description='',actions=''){return `<div class="page-head"><div><h1>${h(title)}</h1>${description?`<p>${h(description)}</p>`:''}</div><div class="row">${actions}</div></div>`;}
function help(key){return `<p class="help">${h(t(key))}</p>`;}
function empty(){return `<div class="card empty"><div class="big-icon"><img class="empty-logo" src="../../assets/emblem.svg" alt=""></div><span class="micro">ARK: SURVIVAL ASCENDED</span><h1>${h(t('emptyTitle'))}</h1><p>${h(t('emptyHelp'))}</p><div class="row">${btn('new',t('newServer'),'plus','primary')}${btn('import',t('importServer'),'import')}</div></div>`;}
function page(){if(view==='servers')return fleetPage();if(view==='preferences')return preferences();if(view==='clusters')return clustersPage();if(view==='activity')return activityPage();if(!server())return empty();return ({overview,configuration,players:playersPage,mods:modsPage,backups:backupsPage,templates:templatesPage,discord:discordPage,console:consolePage}[view]||overview)();}
function events(items){return items.length?items.map(e=>`<div class="event"><div class="event-icon">${icon(e.type.includes('backup')?'backups':e.type.includes('command')?'console':'activity')}</div><div><p>${h(e.message)}</p><time>${h(date(e.at))} · ${h(state.servers.find(s=>s.id===e.serverId)?.name||'Manager')}</time></div></div>`).join(''):`<p class="help">${h(t('noActivity'))}</p>`;}
function overview(){const s=server(),backups=state.backups.filter(b=>b.serverId===s.id),cluster=state.clusters.find(c=>c.id===s.clusterId);return heading(t('overview'),s.map,btn('folder',t('openFolder'),'folder'))+`<div class="card hero"><div class="row spread"><span class="micro">ARK: SURVIVAL ASCENDED</span>${status(s)}</div><h2>${h(s.name)}</h2><p class="muted">${h(s.map)} <span aria-hidden="true"> · </span> ${s.port} / ${s.queryPort} / RCON ${s.rconPort}</p><div class="row">${btn('start',t('start'),'play','primary',s.status!=='stopped'?'disabled':'')}${btn('stop',t('stop'),'stop','',!s.pid?'disabled':'')}${btn('restart',t('restart'),'restart','',!s.pid?'disabled':'')}</div></div><div class="stats"><div class="card stat"><div class="label">${icon('players')}${h(t('players'))}</div><div class="value">${s.playerCount??'—'} <span class="muted">/ ${s.maxPlayers}</span></div><div class="sub">${h(t(s.playerCount==null?'unknown':'online'))}</div></div><div class="card stat"><div class="label">${icon('download')}${h(t('installedVersion'))}</div><div class="value">${h(s.version.gameVersion||t('unknown'))}</div><div class="sub">${h(t('steamBuild'))}: ${h(s.version.build||'—')}</div></div><div class="card stat"><div class="label">${icon('mods')}${h(t('mods'))}</div><div class="value">${s.mods.length}</div><div class="sub">CurseForge · ${s.passiveMods.length} ${h(t('passiveMods'))}</div></div><div class="card stat"><div class="label">${icon('backups')}${h(t('backups'))}</div><div class="value">${backups.length}</div><div class="sub">${h(backups[0]?date(backups[0].createdAt):t('noBackup'))}</div></div></div><div class="grid"><section class="card"><h2>${h(t('quickActions'))}</h2><div class="stack"><div class="row">${btn('install',t('update'),'download')}${btn('backup',t('backupNow'),'backups')}</div><div class="notice">${h(t('keepOpen'))}</div><div><p class="file-label">${h(t('folder'))}</p><code>${h(s.folder)}</code></div><div class="row"><span class="badge">${h(t(s.version.installed?'installed':'missing'))}</span>${cluster?`<span class="badge">${icon('clusters')}${h(cluster.name)}</span>`:''}</div><div><p class="file-label">${h(t('uptime'))}</p><p>${h(s.pid?date(s.startedAt):'—')}</p></div></div></section><section class="card"><div class="section-head"><h2>${h(t('recentActivity'))}</h2>${btn('nav',t('activity'),'chevron','small ghost','data-view="activity"')}</div>${events(state.events.filter(e=>!e.serverId||e.serverId===s.id).slice(0,5))}</section></div>`;}
function basicFields(s,creation=false){return `<div class="grid">${field('name',t('name'),s.name,'text','required maxlength="120"')}${select('map',t('map'),[...new Set([...(state.maps||[]),...(s.map?[s.map]:[])])],s.map)}${field('port',t('gamePort'),s.port,'number','required min="1024" max="65534"')}${field('queryPort',t('queryPort'),s.queryPort,'number','required min="1024" max="65534"')}${field('rconPort',t('rconPort'),s.rconPort,'number','required min="1024" max="65534"')}${field('maxPlayers',t('slots'),s.maxPlayers,'number','required min="1" max="1000"')}${select('platform',t('platform'),['ALL','PC','PS5','XSX','WINGDK','PC+PS5+XSX','PC+WINGDK'],s.platform||'ALL')}${field('customMap',t('map')+' · custom',state.maps.includes(s.map)?'':s.map,'text','placeholder="MyMap_WP"')}${creation?'':field('altSave',t('altSave'),s.altSave||'')}</div>`;}
function settingsData(form){const f=new FormData(form);return {name:f.get('name'),map:f.get('customMap')?.trim()||f.get('map'),port:Number(f.get('port')),queryPort:Number(f.get('queryPort')),rconPort:Number(f.get('rconPort')),maxPlayers:Number(f.get('maxPlayers')),platform:f.get('platform'),altSave:f.get('altSave')||''};}
function configuration(){const s=server();const tabs=['basics','catalog','editor'];let body='';
  if(configTab==='basics')body=`<section class="card">${help('stopFirst')}<form id="basics-form" data-dirty>${basicFields(s)}<div class="divider"></div><div class="grid">
    ${field('serverPassword',t('joinPassword'),'','password','maxlength="128" autocomplete="new-password" aria-describedby="edit-join-password-help"')}
    ${check('removeServerPassword',t('removeJoinPassword'),false)}
  </div><p class="help" id="edit-join-password-help">${h(t('editJoinPasswordHelp'))}</p><div class="divider"></div><label>${h(t('launchArgs'))}<textarea name="extraArgs" class="mono" placeholder="-culture=en">${h((s.extraArgs||[]).join('\n'))}</textarea></label><div class="divider"></div><div class="checkboxes">${state.flags.map(f=>check('flag',f,s.flags.includes(f),`value="${h(f)}"`)).join('')}</div><div class="form-actions">${btn('launchPreview',t('launchPreview'),'console')}<button class="primary" type="submit">${icon('save')}${h(t('save'))}</button></div></form></section>`;
  else if(!configs||configServer!==selected)body=`<div class="card">${h(t('pending'))}</div>`;
  else if(configTab==='editor')body=`<section class="card">${help('editorHelp')}<div class="row spread"><select id="ini-file" aria-label="INI">${Object.keys(configs).map(n=>`<option ${n===file?'selected':''}>${h(n)}</option>`).join('')}</select><div class="row">${btn('importIni',t('import'),'import','small')}${btn('exportIni',t('export'),'download','small')}${btn('reloadConfig',t('reset'),'refresh','small')}</div></div><form id="ini-form" data-dirty><p class="help"><code>${h(s.folder)}\ShooterGame\Saved\Config\WindowsServer\${h(file)}</code></p><textarea id="ini-text" name="text" class="ini-editor" spellcheck="false" aria-label="${h(file)}">${h(configs[file].text)}</textarea><div class="form-actions"><button type="submit" class="primary">${icon('save')}${h(t('save'))}</button></div></form></section>`;
  else body=`<section class="card">${help('catalogHelp')}<div class="row spread"><span class="badge">${state.catalog.length} ${h(t('settingsCount'))}</span>${btn('wiki',t('help'),'link','small')}</div><div class="divider"></div><div class="catalog-tools"><input id="catalog-search" type="search" placeholder="${h(t('search'))}" aria-label="${h(t('search'))}"><select id="catalog-group" aria-label="${h(t('all'))}">${['all','rates','rules','breeding','stats','network','advanced'].map(g=>`<option value="${g}">${h(t(g))}</option>`).join('')}</select></div><form id="catalog-form" data-dirty><div class="catalog-list">${state.catalog.map((c,i)=>catalogField(c,i)).join('')}</div><div class="form-actions"><button type="submit" class="primary">${icon('save')}${h(t('save'))}</button></div></form></section>`;
  return heading(t('configuration'),s.name)+`<div class="tabs">${tabs.map(n=>btn('configTab',t(n),'',configTab===n?'active':'',`data-tab="${n}"`)).join('')}</div>`+body;
}
function iniGet(text,section,key){let current='',value='';for(const line of text.split(/\r?\n/)){const s=line.match(/^\s*\[([^\]]+)\]/);if(s){current=s[1];continue;}const p=line.indexOf('=');if(p>=0&&!/^[;#]/.test(line.trim())&&current.toLowerCase()===section.toLowerCase()&&line.slice(0,p).trim().toLowerCase()===key.toLowerCase())value=line.slice(p+1).trim();}return value;}
function iniSet(text,section,key,value){const nl=text.includes('\r\n')?'\r\n':'\n';const lines=text.split(/\r?\n/);let current='',found=false,sectionIndex=-1,end=lines.length;for(let i=0;i<lines.length;i++){const s=lines[i].match(/^\s*\[([^\]]+)\]/);if(s){if(current.toLowerCase()===section.toLowerCase())end=i;current=s[1];if(current.toLowerCase()===section.toLowerCase()){sectionIndex=i;end=lines.length;}continue;}const p=lines[i].indexOf('=');if(current.toLowerCase()===section.toLowerCase()&&p>=0&&!/^[;#]/.test(lines[i].trim())&&lines[i].slice(0,p).trim().toLowerCase()===key.toLowerCase()){lines[i]=`${key}=${value}`;found=true;}}if(!found){if(sectionIndex<0)lines.push('',`[${section}]`,`${key}=${value}`,'');else lines.splice(end,0,`${key}=${value}`);}return lines.join(nl);}
function catalogField(c,i){if(c.group==='advanced')return `<div class="catalog-field" data-key="${h(c.key.toLowerCase())}" data-group="advanced"><code>${h(c.key)}</code><small>${h(t('arrayHelp'))}</small>${btn('arrayEditor',t('manage'),'configuration','small',`data-file="${h(c.file)}"`)}</div>`;const value=iniGet(configs[c.file].text,c.section,c.key);return `<label class="catalog-field" data-key="${h(c.key.toLowerCase())}" data-group="${c.group}"><code>${h(c.key)}</code><small>${h(c.file)} · [${h(c.section)}]</small>${c.type==='boolean'?`<select name="key-${i}" data-initial="${h(value.toLowerCase()==='true'?'True':value.toLowerCase()==='false'?'False':'')}"><option value="" ${!value?'selected':''}>—</option><option value="True" ${value.toLowerCase()==='true'?'selected':''}>True</option><option value="False" ${value.toLowerCase()==='false'?'selected':''}>False</option></select>`:`<input name="key-${i}" type="${c.type==='number'?'number':c.type==='password'?'password':'text'}" ${c.type==='number'?'step="any"':''} value="${h(value)}" data-initial="${h(value)}" placeholder="${h(c.default??'—')}">`}</label>`;}
function playersPage(){const s=server(),list=state.players[s.id]||[];return heading(t('players'),s.name,btn('readSave',t('readSave'),'backups')+btn('refreshPlayers',t('refresh'),'refresh','primary'))+`<div class="notice">${h(t('playersHelp'))}<br><br>${h(t('saveReaderHelp'))}</div>${s.saveReadReport?`<div class="card toolbar-bottom"><h3>${h(t('savegame'))} · ${s.saveReadReport.players} ${h(t('players'))}</h3><p class="help">${h(date(s.saveReadReport.at))}</p>${s.saveReadReport.warnings.length||s.saveReadReport.unresolved.length?`<pre>${h([...s.saveReadReport.warnings,...s.saveReadReport.unresolved.map(p=>(p.characterName||'—')+' · '+(p.playerId||'—')+' · EOS: —')].join('\n'))}</pre>`:''}</div>`:''}<div class="card toolbar-bottom"><div class="table-wrap"><table><thead><tr>${['playerName','identity','tribe','lastSeen','actions'].map(k=>`<th>${h(t(k))}</th>`).join('')}</tr></thead><tbody>${list.map(p=>`<tr><td><div class="row"><span class="dot ${p.online?'green':''}"></span><strong>${h(p.name||p.characterName||t('unknown'))}</strong></div><div class="player-account">${h(p.accountId)}</div><div class="file-label">${h(t(p.online?'online':'offline'))}</div></td><td>${h(p.characterName||'—')}<div class="player-account">${h(t('playerId'))}: ${h(p.playerId||'—')}</div><div class="player-account">${h(t('source'))}: ${h(t(p.metadataSource||'RCON'))}</div></td><td>${h(p.tribeName||'—')}<div class="player-account">${h(p.tribeId||'—')}</div></td><td>${h(date(p.lastSeen))}</td><td>${btn('player',t('actions'),'players','small',`data-player="${h(p.accountId)}"`)}</td></tr>`).join('')||`<tr><td colspan="5">${h(t('noPlayers'))}</td></tr>`}</tbody></table></div><div class="divider"></div><form id="snapshot-form" data-dirty>${browseField('playerSnapshot',t('snapshot'),s.playerSnapshot||'','snapshot')}<div class="form-actions"><button type="submit">${h(t('save'))}</button></div></form></div>`;}
function modsPage(){const s=server();return heading(t('mods'),s.name,btn('curseforge','CurseForge','link'))+`<div class="card">${help('modHelp')}<form id="mods-form" data-dirty><div class="grid"><label>${h(t('activeMods'))}<textarea name="mods" class="mono" placeholder="928708, 900062">${h(s.mods.join(', '))}</textarea></label><label>${h(t('passiveMods'))}<textarea name="passiveMods" class="mono" placeholder="">${h(s.passiveMods.join(', '))}</textarea></label></div><div class="form-actions"><button type="submit" class="primary">${icon('save')}${h(t('save'))}</button></div></form></div>`;}
function clustersPage(){return heading(t('clusters'),'',btn('clusterNew',t('createCluster'),'plus','primary'))+`<div class="notice">${h(t('clusterHelp'))}</div><div class="grid toolbar-bottom">${state.clusters.map(c=>{const members=state.servers.filter(s=>s.clusterId===c.id);return `<div class="card"><div class="section-head"><h2>${h(c.name)}</h2><span class="badge">${members.length} ${icon('server')}</span></div><code>${h(c.id)}</code><p class="help">${h(c.folder)}</p>${members.map(s=>`<div class="server-chip"><div class="row spread"><strong>${h(s.name)}</strong>${btn('detach',t('detach'),'link','small',`data-id="${s.id}"`)}</div><small>${h(s.map)}</small></div>`).join('')}<div class="form-actions">${btn('clusterEdit',t('edit'),'configuration','small',`data-id="${h(c.id)}"`)}</div></div>`;}).join('')||`<div class="card">${h(t('noItems'))}</div>`}</div>`;}
function dayNames(){return Array.from({length:7},(_,i)=>new Intl.DateTimeFormat(currentLanguage,{weekday:'short'}).format(new Date(2026,10,1+i)));}
function backupsPage(){const s=server(),list=state.backups.filter(b=>b.serverId===s.id),scheduleList=state.schedules.filter(b=>b.serverId===s.id);return heading(t('backups'),s.name,btn('backup',t('backupNow'),'backups','primary'))+`<div class="notice">${h(t('backupHelp'))}</div><section class="card toolbar-bottom"><h2>${h(t('schedules'))}</h2><p class="help">${h(state.timezone)} · ${h(t('times'))}</p><form id="schedule-form"><label>${h(t('days'))}<span class="day-pills">${dayNames().map((d,i)=>check('days',d,true,`value="${i}"`)).join('')}</span></label><div class="row toolbar-bottom"><label class="grow">${h(t('times'))}<input name="times" placeholder="06:00, 12:30, 23:00" value="06:00, 18:00" required></label><button type="submit" class="primary">${icon('plus')}${h(t('addSchedule'))}</button></div></form><div class="divider"></div>${scheduleList.map(x=>`<div class="row spread server-chip"><div><strong>${h(x.days.map(i=>dayNames()[i]).join(', '))}</strong><p class="help">${h(x.times.join(' · '))}</p><small>${h(t('lastSeen'))}: ${h(x.lastRun||'—')}${x.lastError?` · ${h(x.lastError)}`:''}</small></div><div class="row">${btn('toggleSchedule',t(x.enabled?'enabled':'stopped'),'','small',`data-id="${x.id}"`)}${btn('removeSchedule',t('remove'),'trash','small danger',`data-id="${x.id}"`)}</div></div>`).join('')||`<p class="help">${h(t('noItems'))}</p>`}</section><section class="card toolbar-bottom"><div class="section-head"><h2>${h(t('diskBackups'))}</h2>${btn('backupFolder',t('openFolder'),'folder','small')}</div><div class="table-wrap"><table><thead><tr><th>${h(t('name'))}</th><th>SHA-256</th><th>${h(t('actions'))}</th></tr></thead><tbody>${list.map(b=>`<tr><td>${h(date(b.createdAt))}<div class="file-label">${h(bytes(b.bytes))} · ${h(b.reason)}</div></td><td><code>${h(b.sha256.slice(0,24))}…</code></td><td>${btn('restore',t('restore'),'restart','small',`data-id="${b.id}"`)}</td></tr>`).join('')||`<tr><td colspan="3">${h(t('noBackup'))}</td></tr>`}</tbody></table></div></section>`;}
function templatesPage(){return heading(t('templates'),server().name,btn('importTemplate',t('import'),'import'))+`<div class="notice">${h(t('templateHelp'))}</div><div class="card toolbar-bottom"><form id="template-form"><div class="row spread">${field('name',t('templateName'),'','text','required maxlength="120"')}<button class="primary" type="submit">${icon('plus')}${h(t('saveTemplate'))}</button></div></form></div><div class="grid toolbar-bottom">${state.templates.map(x=>`<div class="card"><h2>${h(x.name)}</h2><p class="help">${h(date(x.createdAt))} · ${x.mods.length} ${h(t('mods'))}</p><div class="row">${btn('applyTemplate',t('apply'),'templates','primary',`data-id="${x.id}"`)}${btn('exportTemplate',t('export'),'download','',`data-id="${x.id}"`)}</div></div>`).join('')||`<div class="card">${h(t('noItems'))}</div>`}</div>`;}
function discordPanelCard(){
  const d=state.settings,status=state.discordPanelStatus||{};
  return `<section class="card toolbar-bottom">
    <h2>${h(t('discordPanel'))}</h2>${help('discordPanelHelp')}
    ${status.error?`<p class="notice warning" role="status">${h(status.error)}</p>`:''}
    ${status.ipUnavailable?`<p class="notice warning" role="status">${h(t('discordPanelIpError'))}</p>`:''}
    ${status.updatedAt?`<p class="help">${h(t('discordPanelUpdated'))} · ${h(date(status.updatedAt))}</p>`:''}
    <form id="discord-panel-form" data-dirty>
      <div class="grid">
        ${field('discordPanelChannelId',t('discordPanelChannel'),d.discordPanelChannelId||'','text','inputmode="numeric" pattern="[0-9]{15,25}"')}
        ${field('discordPanelAddress',t('discordPanelAddress'),d.discordPanelAddress||'','text','maxlength="253" placeholder="ark.example.com"')}
      </div>
      ${check('discordPanelAutoIp',t('discordPanelAutoIp'),d.discordPanelAutoIp)}
      <div class="form-actions">
        ${status.url?btn('openDiscordPanel',t('discordPanelOpen'),'link','small'):''}
        <button type="submit" class="primary">${h(t('save'))}</button>
      </div>
    </form>
  </section>`;
}
function discordPage(){const s=server(),d=s.discord||{};return heading(t('discord'),s.name)+discordPanelCard()+`<div class="grid"><section class="card"><h2>${h(t('discord'))}</h2>${help('webhookHelp')}<form id="discord-form" data-dirty>${field('webhook',t('webhook'),d.webhook||'','password','autocomplete="off"')}<div class="divider"></div>${['starting','ready','stopping','restarting','exited','updating','backup'].map(type=>field('event-'+type,t(type),d.messages?.[type]||'','text','maxlength="1800"')).join('<br>')}<div class="divider"></div>${check('chat',t('chatBridge'),d.chat)}<div class="form-actions">${btn('testWebhook',t('testWebhook'),'discord')}<button class="primary" type="submit">${h(t('save'))}</button></div></form></section><div class="stack"><section class="card"><h2>${h(t('bridgeGroup'))}</h2>${help('bridgeHelp')}<form id="bridge-form" data-dirty>${field('bridgeGroup',t('bridgeGroup'),s.bridgeGroup||'','text','placeholder="chispi-global"')}<div class="form-actions"><button type="submit" class="primary">${h(t('save'))}</button></div></form></section><section class="card"><h2>Discord → ARK</h2>${help('botHelp')}${help('botOutboundHelp')}${state.discordError?`<p class="notice warning" role="status">${h(state.discordError==='messageContentMissing'?t('messageContentMissing'):state.discordError)}</p>`:''}<form id="bot-form" data-dirty>${field('botToken',t('botToken'),state.settings.botToken||'','password','autocomplete="off"')}<br>${field('channelId',t('channelId'),state.settings.channelId||'')}<br>${field('discordGuildId',t('discordGuild'),state.settings.discordGuildId||'')}<br>${check('discordInbound',t('inbound'),state.settings.discordInbound)}<div class="form-actions">${btn('checkBot',t('checkBot'),'discord','small')}${btn('developerPortal','Discord Developer Portal','link','small')}<button type="submit" class="primary">${h(t('save'))}</button></div></form></section></div></div><section class="card toolbar-bottom"><h2>${h(t('bridgeLog'))}</h2><pre>${h(state.chat.filter(c=>c.serverId===s.id).map(c=>`${date(c.at)} · ${c.name} (${c.map}): ${c.message}`).join('\n')||t('noItems'))}</pre></section>`;}
function consolePage(){const s=server();if(consoleTab==='steam')return heading(t('steamConsole'),s.name)+consoleTabs()+steamConsolePanel();return heading(t('console'),s.name)+consoleTabs()+`<section class="card">${help('consoleHelp')}<form id="command-form" class="command-form"><input name="text" placeholder='Broadcast "Cierre de servidor en 10m"' aria-label="${h(t('command'))}" required autocomplete="off"><button type="submit" class="primary">${icon('console')}${h(t('send'))}</button></form><div class="row toolbar-bottom">${['ListPlayers','SaveWorld','GetChat','GetGameLog'].map(c=>btn('prefillCommand',c,'','small',`data-command="${c}"`)).join('')}${btn('commandsWiki',t('help'),'link','small ghost')}</div><pre id="command-output">${h(commandHistory[selected]?.join('\n\n')||'› RCON')}</pre></section><section class="card toolbar-bottom"><h2>${h(t('output'))}</h2><pre>${h((state.logs[s.id]||[]).join('\n')||'—')}</pre></section>`;}
const commandHistory={};
let consoleTab='game',steamOutput='',steamSession=null,steamFollow=true;
function consoleTabs(){return `<div class="tabs">${btn('consoleTab',t('gameConsole'),'console',consoleTab==='game'?'active':'','data-tab="game"')}${btn('consoleTab',t('steamConsole'),'download',consoleTab==='steam'?'active':'','data-tab="steam"')}</div>`;}
function steamConsolePanel(){const s=server();return `<section class="card"><div class="row spread"><h2>SteamCMD · ${h(s.name)}</h2><div class="row">${btn('install',t('update'),'download','primary',s.status!=='stopped'?'disabled':'')}${btn('steamRefresh',t('refresh'),'refresh','small')}${btn('exportSteamLog',t('exportLog'),'download','small')}</div></div>${help('steamConsoleHelp')}<div id="steam-session" class="notice">${steamSummary()}</div><div class="row spread toolbar-bottom">${check('follow',t('autoScroll'),steamFollow,'id="steam-follow"')}<span class="file-label">${h(s.folder)}</span></div><pre id="steam-output" class="steam-terminal" tabindex="0" aria-label="${h(t('steamConsole'))}">${h(steamOutput||t('updateReady'))}</pre></section>`;}
function steamSummary(){if(!steamSession)return h(t('updateReady'));return `<span class="badge ${steamSession.status==='success'?'good':''}">${h(t(steamSession.status==='running'?'updating':steamSession.status))}</span> <span>${h(date(steamSession.startedAt))} · ${h(t('attempt'))}: ${steamSession.attempt||1} · ${h(t('exitCode'))}: ${h(steamSession.exitCode??'—')}</span>${steamSession.error?`<p class="steam-error">${h(steamSession.error)}</p>`:''}`;}
async function refreshSteam(){if(!selected||view!=='console'||consoleTab!=='steam')return;const id=selected,result=await api('steamConsole',id);if(selected!==id||view!=='console'||consoleTab!=='steam')return;steamOutput=result.output;steamSession=result.session;const installButton=$('#page [data-action="install"]');if(installButton)installButton.disabled=result.busy||!!server()?.pid;const output=$('#steam-output');if(output){const top=output.scrollTop;output.textContent=steamOutput||t('updateReady');output.scrollTop=steamFollow?output.scrollHeight:top;}const summary=$('#steam-session');if(summary)summary.innerHTML=steamSummary();}
window.asa.onEvent?.(event=>{if(event.type!=='steam-output'||event.serverId!==selected)return;steamOutput=(steamOutput+event.text).slice(-128000);const output=$('#steam-output');if(output){const top=output.scrollTop;output.textContent=steamOutput;output.scrollTop=steamFollow?output.scrollHeight:top;}});
setInterval(()=>refreshSteam().catch(error=>toast(errorMessage(error),true)),1000);
function fleetPage(){const list=state.servers;if(!list.length)return heading(t('servers'),t('fleetHelp'))+empty();return heading(t('servers'),t('fleetHelp'),btn('new',t('newServer'),'plus','primary')+btn('import',t('importServer'),'import'))+`<div class="fleet-summary"><span class="badge">${list.length} ${h(t('fleet'))}</span><span class="badge good">${list.filter(s=>s.status==='running').length} ${h(t('online'))}</span><span class="badge">${list.filter(s=>s.status==='stopped').length} ${h(t('stopped'))}</span></div><input id="fleet-search" class="fleet-search" type="search" placeholder="${h(t('filterServers'))}" aria-label="${h(t('filterServers'))}"><div class="fleet-grid">${list.map(s=>{const cluster=state.clusters.find(c=>c.id===s.clusterId),backup=state.backups.find(b=>b.serverId===s.id);return `<article class="card fleet-card ${s.id===selected?'selected-server':''}" data-search="${h((s.name+' '+s.map+' '+(cluster?.name||'')).toLowerCase())}"><div class="row spread"><span class="micro">${h(s.map.replace(/_WP$/,'').replace(/([a-z])([A-Z])/g,'$1 $2'))}</span>${status(s)}</div><h2>${h(s.name)}</h2><div class="fleet-metrics"><div><span>${h(t('players'))}</span><strong>${s.playerCount??'—'} / ${s.maxPlayers}</strong></div><div><span>${h(t('installedVersion'))}</span><strong>${h(s.version.gameVersion||t('unknown'))}</strong></div></div><p class="fleet-path" title="${h(s.folder)}">${h(s.folder)}</p><div class="row"><span class="badge">UDP ${s.port}</span><span class="badge">RCON ${s.rconPort}</span>${cluster?`<span class="badge">${h(cluster.name)}</span>`:''}</div><p class="help">${h(t('lastBackup'))}: ${h(backup?date(backup.createdAt):t('noBackup'))}</p>${s.steamUpdate?`<p class="steam-update-note ${s.steamUpdate.status==='error'?'steam-error':''}">SteamCMD · ${h(t(s.steamUpdate.status==='running'?'updating':s.steamUpdate.status))}</p>`:''}<div class="row fleet-controls">${btn('selectServer',t('manageServer'),'configuration','primary',`data-id="${s.id}"`)}${btn(s.pid?'stop':'start',t(s.pid?'stop':'start'),s.pid?'stop':'play','small',`data-id="${s.id}" ${s.status!=='stopped'&&!s.pid?'disabled':''}`)}${btn('install',t('update'),'download','small',`data-id="${s.id}" ${s.status!=='stopped'?'disabled':''}`)}</div></article>`;}).join('')}</div>`;}
function activityPage(){return heading(t('activity'))+`<section class="card">${events(state.events.slice(0,100))}<h3 class="toolbar-bottom">Discord</h3><pre>${h((state.logs.discord||[]).join('\n')||'—')}</pre></section>`;}
function preferences(){return heading(t('preferences'))+`<div class="stack"><section class="card"><form id="preferences-form" data-dirty><div class="grid">${select('language',t('language'),Object.entries(LANGS),currentLanguage)}${select('theme',t('theme'),[['dark',t('dark')],['light',t('light')]],state.settings.theme)}<div class="full">${browseField('steamcmd',t('steamcmd'),state.settings.steamcmd||'','steamcmd')}</div></div>${help('steamHelp')}${help('steamRepairHelp')}<div class="row">${btn('steamGuide',t('getSteam'),'link','small')}${btn('downloadSteam',t('repairSteam'),'download','small')}</div><div class="form-actions"><button type="submit" class="primary">${icon('save')}${h(t('save'))}</button></div></form></section><section class="card"><h2>${h(t('dataFolder'))}</h2><code>${h(state.dataDir)}</code><p class="help">${h(t('keepOpen'))}</p>${btn('dataFolder',t('openFolder'),'folder','small')}</section>${state.servers.length?`<section class="card"><div class="row spread"><div><h2>${h(t('unregister'))}</h2><p class="help">${h(server()?.name)}</p></div>${btn('unregister',t('unregister'),'trash','danger')}</div></section>`:''}</div>`;}
function render(){document.documentElement.lang=currentLanguage;document.body.className=state.settings.theme==='light'?'light':'';$('#app').innerHTML=shell();}
async function refresh(renderUI=true){await load();if(renderUI)render();}
function errorMessage(error){return error?.message||String(error);}
async function discard(){if(!dirty)return true;return confirmDialog(t('notSaved'));}
function modal(title,body,submitLabel,submit){const dialog=$('#dialog');if(dialog.open)dialog.close();dialog.innerHTML=`<h2>${h(title)}</h2><form id="modal-form"><div class="dialog-scroll">${body}</div><div class="error" role="alert"></div><div class="form-actions">${btn('cancelDialog',t('cancel'))}${submitLabel?`<button class="primary" type="submit">${h(submitLabel)}</button>`:''}</div></form>`;dialog.showModal();if(submit)$('#modal-form').addEventListener('submit',async e=>{e.preventDefault();const submitBtn=e.submitter;if(submitBtn)submitBtn.disabled=true;try{await submit(e.target);dialog.close();}catch(err){dialog.querySelector('.error').textContent=errorMessage(err);}finally{if(submitBtn)submitBtn.disabled=false;}});}
function confirmDialog(message){return new Promise(resolve=>{modal(t('confirm'),`<p>${h(message)}</p>`,t('confirm'),async()=>resolve(true));$('#dialog').addEventListener('close',()=>resolve(false),{once:true});});}
function formValue(form,name){return new FormData(form).get(name);}
async function serverDialog(importing){
  const s={name:'Chispi · The Island',map:'TheIsland_WP',port:7777+state.servers.length*10,queryPort:27015+state.servers.length*10,rconPort:27020+state.servers.length*10,maxPlayers:70,platform:'ALL'};
  let inspection=null;
  modal(t(importing?'importServer':'newServer'),help(importing?'importHelp':'createHelp')+browseField('folder',t('folder'),'')+(importing?`<div class="form-actions">${btn('inspect',t('inspect'),'refresh','primary')}</div><div id="migration-preview"></div>`:`<div class="divider"></div>${basicFields(s,true)}<div class="divider"></div><div class="grid">
    ${field('serverPassword',t('joinPassword'),'','password','maxlength="128" autocomplete="new-password" aria-describedby="join-password-help"')}
    ${field('adminPassword',t('adminPassword'),'','password','maxlength="128" autocomplete="new-password" aria-describedby="admin-password-help"')}
    <small class="help" id="join-password-help">${h(t('joinPasswordHelp'))}</small><small class="help" id="admin-password-help">${h(t('adminPasswordHelp'))}</small>
  </div>`),t(importing?'import':'newServer'),async form=>{
    if(importing&&!inspection)throw Error(t('inspect'));
    const data={...settingsData(form),folder:formValue(form,'folder'),extraArgs:importing?String(formValue(form,'extraArgs')||'').split(/\r?\n/).filter(Boolean):[],clusterReviewed:!!form.querySelector('[name="clusterReviewed"]')?.checked};
    if(importing){data.mods=inspection.mods;data.passiveMods=inspection.passiveMods;data.altSave=inspection.altSave;}
    else{data.serverPassword=formValue(form,'serverPassword');data.adminPassword=formValue(form,'adminPassword');}
    const result=await api(importing?'import':'create',data);selected=result.id;view='overview';configs=null;dirty=false;await refresh();toast(t('saved'));
  });
  if(importing){$('#dialog').addEventListener('click',async function inspectClick(e){const b=e.target.closest('[data-action="inspect"]');if(!b)return;b.disabled=true;try{inspection=await api('inspect',formValue($('#modal-form'),'folder'));$('#migration-preview').innerHTML=`<div class="divider"></div><h3>${h(t('migration'))}</h3><p class="help">${h(inspection.scripts.join(', ')||t('unknown'))}</p>${!inspection.rconEnabled||!inspection.adminConfigured?`<div class="notice warning">${h(t('noRcon'))}</div><br>`:''}${basicFields({...inspection,map:inspection.map||'TheIsland_WP'})}<div class="divider"></div><label>${h(t('launchArgs'))}<textarea name="extraArgs" class="mono"></textarea></label><p class="help">${h(inspection.detectedCluster)} · ${h(inspection.detectedClusterFolder)}</p>${check('clusterReviewed',t('reviewCluster'),false,'required')}`;}catch(err){$('#dialog .error').textContent=errorMessage(err);}finally{b.disabled=false;}},{signal:dialogSignal()});}
}
let dialogController;
function dialogSignal(){dialogController?.abort();dialogController=new AbortController();$('#dialog').addEventListener('close',()=>dialogController?.abort(),{once:true});return dialogController.signal;}
function clusterDialog(id){const c=state.clusters.find(c=>c.id===id);modal(t('clusters'),help('clusterHelp')+`<div class="grid">${field('id',t('clusterId'),c?.id||'chispi-cluster','text',c?'readonly':'required pattern="[a-zA-Z0-9_-]{3,64}"')}${field('name',t('name'),c?.name||'Chispi Cluster','text','required')}<div class="full">${browseField('folder',t('clusterFolder'),c?.folder||'')}</div><div class="full"><label>${h(t('linked'))}</label><div class="checkboxes toolbar-bottom">${state.servers.map(s=>check('members',s.name+(s.clusterId?' · '+s.clusterId:''),s.clusterId===id,`value="${s.id}"`)).join('')}</div></div></div>`,t('createCluster'),async form=>{const f=new FormData(form);await api('cluster',{id:f.get('id'),name:f.get('name'),folder:f.get('folder'),serverIds:f.getAll('members')});dirty=false;await refresh();toast(t('saved'));});}
function playerDialog(accountId){const p=(state.players[selected]||[]).find(x=>x.accountId===accountId);if(!p)return;modal(t('identity'),`<p><strong>${h(p.name)}</strong></p><code>${h(p.accountId)}</code><div class="divider"></div><div class="grid">${field('characterName',t('character'),p.characterName||'')}${field('playerId',t('playerId'),p.playerId||'','text','pattern="[0-9]*"')}${field('tribeName',t('tribe'),p.tribeName||'')}${field('tribeId',t('tribeId'),p.tribeId||'','text','pattern="[0-9]*"')}</div><p class="help">${h(t('manual'))} · ${h(date(p.metadataAt))}</p><div class="row">${['kick','ban','unban','admin','revokeAdmin'].map(action=>btn('player-'+action,t(action),'',action==='ban'?'small danger':'small',`data-player="${h(accountId)}"`)).join('')}</div><div class="divider"></div><h3>${h(t('teleport'))}</h3>${help('teleportHelp')}${p.playerId?['cheat TeleportToPlayer '+p.playerId,'cheat TeleportPlayerIDToMe '+p.playerId].map(c=>`<div class="row spread server-chip"><code>${h(c)}</code>${btn('copy',t('copy'),'copy','small',`data-text="${h(c)}"`)}</div>`).join(''):`<p class="notice">${h(t('playerId'))}: ${h(t('unknown'))}</p>`}`,t('save'),async form=>{const f=new FormData(form);await api('metadata',{id:selected,accountId,characterName:f.get('characterName'),playerId:f.get('playerId'),tribeName:f.get('tribeName'),tribeId:f.get('tribeId')});await refresh();toast(t('saved'));});}
async function action(button){const a=button.dataset.action,s=server();
  if(a==='cancelDialog'){$('#dialog').close();return;}
  if(a==='copy'){await navigator.clipboard.writeText(button.dataset.text);toast(t('clipboard'));return;}
  if(a==='browse'){const value=await api('choose',button.dataset.kind);if(value){const form=button.closest('form');form.elements[button.dataset.target].value=value;if(form.hasAttribute('data-dirty'))dirty=true;const preview=$('#migration-preview');if(preview)preview.innerHTML='';}return;}
  if(a==='new'||a==='import'){if(await discard())await serverDialog(a==='import');return;}
  if(a==='selectServer'){if(!await discard())return;selected=button.dataset.id;view='overview';dirty=false;configs=null;render();return;}
  if(a==='consoleTab'){consoleTab=button.dataset.tab;render();if(consoleTab==='steam')await refreshSteam();return;}
  if(a==='steamRefresh'){await refreshSteam();return;}
  if(a==='exportSteamLog'){await api('exportSteamLog',selected);return;}
  if(a==='nav'){if(!await discard())return;dirty=false;view=button.dataset.view;if(view==='console'&&consoleTab==='steam')await refreshSteam();if(view==='configuration'&&configTab!=='basics')await getConfigs();render();return;}
  if(a==='configTab'){if(!await discard())return;dirty=false;configTab=button.dataset.tab;if(configTab!=='basics')await getConfigs();render();return;}
  if(a==='refresh'){if(!await discard())return;dirty=false;await refresh();if(view==='configuration'&&configTab!=='basics'){await getConfigs();render();}return;}
  if(a==='theme'){if(!await discard())return;dirty=false;await api('settings',{theme:state.settings.theme==='dark'?'light':'dark'});await refresh();return;}
  if(a==='folder'||a==='backupFolder'||a==='dataFolder'){await api('openFolder',{id:s?.id,kind:a==='backupFolder'?'backups':a==='dataFolder'?'data':'server'});return;}
  const links={wiki:'https://ark.wiki.gg/wiki/Server_configuration',commandsWiki:'https://ark.wiki.gg/wiki/Console_commands',curseforge:'https://www.curseforge.com/ark-survival-ascended',steamGuide:'https://developer.valvesoftware.com/wiki/SteamCMD#Downloading_SteamCMD',developerPortal:'https://discord.com/developers/applications'};
  if(links[a]){await api('external',links[a]);return;}
  if(a==='downloadSteam'){if(!await discard())return;toast(t('pending'));await api('downloadSteam');dirty=false;await refresh();toast(t('saved'));return;}
  if(['start','stop','restart','install','backup'].includes(a)){const target=button.dataset.id||selected;if(a!=='start'&&!await confirmDialog((state.servers.find(s=>s.id===target)?.name||'')+' · '+(a==='backup'?t('backupHelp'):t('safety'))))return;selected=target;if(a==='install'){view='console';consoleTab='steam';steamOutput='';steamSession=null;render();}toast(t('pending'));const promise=api(a,target);setTimeout(()=>refresh().catch(()=>{}),700);try{await promise;await refresh();toast(t('saved'));}finally{if(a==='install')await refreshSteam();}return;}
  if(a==='launchPreview'){const form=$('#basics-form'),data={...s,...settingsData(form),extraArgs:String(formValue(form,'extraArgs')||'').split(/\r?\n/).filter(Boolean),flags:new FormData(form).getAll('flag')};const cluster=state.clusters.find(c=>c.id===s.clusterId);const args=[`${data.map}?listen${data.altSave?'?AltSaveDirectoryName='+data.altSave:''}`,`-port=${data.port}`,`-QueryPort=${data.queryPort}`,`-WinLiveMaxPlayers=${data.maxPlayers}`,`-ServerPlatform=${data.platform}`,'-log',...(s.mods.length?['-mods='+s.mods.join(',')]:[]),...(s.passiveMods.length?['-passivemods='+s.passiveMods.join(',')]:[]),...(cluster?['-clusterid='+cluster.id,'-ClusterDirOverride='+cluster.folder,'-NoTransferFromFiltering']:[]),...data.flags.map(f=>'-'+f),...data.extraArgs];modal(t('launchPreview'),`<pre>${h('"'+s.folder+'\\ShooterGame\\Binaries\\Win64\\ArkAscendedServer.exe" '+args.map(a=>/\s/.test(a)?'"'+a+'"':a).join(' '))}</pre>`,null);return;}
  if(a==='reloadConfig'){if(!await discard())return;dirty=false;await getConfigs();render();return;}
  if(a==='importIni'){const text=await api('importIni');if(text!==null){$('#ini-text').value=text;dirty=true;}return;}
  if(a==='exportIni'){await api('exportIni',{file,text:$('#ini-text').value});return;}
  if(a==='refreshPlayers'){await api('players',selected);await refresh();return;}
  if(a==='readSave'){const file=await api('choose','savegame');if(!file)return;toast(t('pending'));await api('readSave',{id:selected,file});await refresh();toast(t('saved'));return;}
  if(a==='openDiscordPanel'){await api('openDiscordPanel');return;}
  if(a==='checkBot'){if(dirty){toast(t('save'),true);return;}const result=await api('discordStatus');toast(t(result.messageContent===false?'messageContentMissing':'botConnected')+' · '+result.botName+' · #'+result.channelName,result.messageContent===false);return;}
  if(a==='arrayEditor'){if(!await discard())return;dirty=false;configTab='editor';file=button.dataset.file;await getConfigs();render();return;}
  if(a==='player'){playerDialog(button.dataset.player);return;}
  if(a.startsWith('player-')){const accountId=button.dataset.player,playerAction=a.slice(7);button.disabled=true;try{if(playerAction==='admin'||playerAction==='revokeAdmin')await api('admin',{id:selected,accountId,enabled:playerAction==='admin'});else await api('playerAction',{id:selected,accountId,action:playerAction});toast(t('saved'));}finally{button.disabled=false;}return;}
  if(a==='clusterNew'||a==='clusterEdit'){if(!await discard())return;clusterDialog(button.dataset.id);return;}
  if(a==='detach'){if(!await confirmDialog(t('safety')))return;await api('detach',button.dataset.id);await refresh();return;}
  if(a==='restore'){if(!await confirmDialog(t('restoreHelp')))return;toast(t('pending'));await api('restore',{id:selected,backupId:button.dataset.id});await refresh();toast(t('saved'));return;}
  if(a==='removeSchedule'){await api('removeSchedule',button.dataset.id);await refresh();return;}
  if(a==='toggleSchedule'){const schedule=state.schedules.find(x=>x.id===button.dataset.id);await api('schedule',{...schedule,enabled:!schedule.enabled});await refresh();return;}
  if(a==='applyTemplate'){if(!await confirmDialog(t('templateHelp')))return;await api('applyTemplate',{serverId:selected,templateId:button.dataset.id});configs=null;await refresh();toast(t('saved'));return;}
  if(a==='exportTemplate'){await api('exportTemplate',button.dataset.id);return;}
  if(a==='importTemplate'){await api('importTemplate');await refresh();return;}
  if(a==='testWebhook'){if(dirty){toast(t('save'),true);return;}await api('testWebhook',{id:selected});toast(t('saved'));return;}
  if(a==='prefillCommand'){$('#command-form [name="text"]').value=button.dataset.command;$('#command-form [name="text"]').focus();return;}
  if(a==='unregister'){if(!await confirmDialog(t('unregisterHelp')))return;await api('remove',selected);selected='';configs=null;dirty=false;await refresh();return;}
}
async function getConfigs(){configs=await api('configs',selected);configServer=selected;}
async function submit(form){const f=new FormData(form),s=server();switch(form.id){
  case 'basics-form':{
    const patch={...settingsData(form),extraArgs:String(f.get('extraArgs')).split(/\r?\n/).filter(Boolean),flags:f.getAll('flag')};
    const password=f.get('serverPassword')?.trim();
    if(f.has('removeServerPassword'))patch.serverPassword='';
    else if(password)patch.serverPassword=password;
    await api('update',{id:selected,patch});
    configs=null;
    break;
  }
  case 'ini-form':configs=await api('saveConfig',{id:selected,file,text:f.get('text'),hash:configs[file].hash});break;
  case 'catalog-form':{const changed={};for(let i=0;i<state.catalog.length;i++){const c=state.catalog[i],el=form.elements['key-'+i];if(el&&el.value!==''&&el.value!==el.dataset.initial){changed[c.file]??=configs[c.file].text;changed[c.file]=iniSet(changed[c.file],c.section,c.key,el.value);}}if(Object.keys(changed).length)configs=await api('saveConfigs',{id:selected,files:Object.fromEntries(Object.entries(changed).map(([file,text])=>[file,{text,hash:configs[file].hash}]))});break;}
  case 'mods-form':await api('update',{id:selected,patch:{mods:String(f.get('mods')).split(/[\s,;]+/).filter(Boolean),passiveMods:String(f.get('passiveMods')).split(/[\s,;]+/).filter(Boolean)}});break;
  case 'snapshot-form':await api('update',{id:selected,patch:{playerSnapshot:f.get('playerSnapshot')}});break;
  case 'schedule-form':await api('schedule',{serverId:selected,days:f.getAll('days').map(Number),times:String(f.get('times')).split(',').map(x=>x.trim()).filter(Boolean),enabled:true});break;
  case 'template-form':await api('template',{serverId:selected,name:f.get('name')});break;
  case 'discord-form':await api('discord',{id:selected,webhook:f.get('webhook'),chat:f.has('chat'),messages:Object.fromEntries(['starting','ready','stopping','restarting','exited','updating','backup'].map(type=>[type,f.get('event-'+type)]))});break;
  case 'bridge-form':await api('update',{id:selected,patch:{bridgeGroup:f.get('bridgeGroup')}});break;
  case 'discord-panel-form':await api('settings',{
    discordPanelChannelId:String(f.get('discordPanelChannelId')).trim(),
    discordPanelAddress:f.get('discordPanelAddress'),
    discordPanelAutoIp:f.has('discordPanelAutoIp')
  });break;
  case 'bot-form':await api('settings',{botToken:f.get('botToken'),channelId:f.get('channelId'),discordGuildId:f.get('discordGuildId'),discordInbound:f.has('discordInbound')});break;
  case 'preferences-form':await api('settings',{language:f.get('language'),theme:f.get('theme'),steamcmd:f.get('steamcmd')});break;
  case 'command-form':{const command=f.get('text');toast(t('pending'));const result=await api('command',{id:selected,text:command});commandHistory[selected]??=[];commandHistory[selected].push('› '+command+'\n'+result);commandHistory[selected]=commandHistory[selected].slice(-50);$('#command-output').textContent=commandHistory[selected].join('\n\n');form.reset();return;}
  default:return;
}dirty=false;await refresh();toast(t('saved'));}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled||b.dataset.action==='inspect')return;action(b).catch(err=>toast(errorMessage(err),true));});
document.addEventListener('submit',async e=>{if(e.target.id==='modal-form')return;e.preventDefault();const button=e.submitter;if(button)button.disabled=true;try{await submit(e.target);}catch(err){toast(errorMessage(err),true);}finally{if(button)button.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.closest('[data-dirty]'))dirty=true;if(e.target.id==='catalog-search'||e.target.id==='catalog-group')filterCatalog();if(e.target.id==='fleet-search'){const query=e.target.value.toLowerCase();$$('.fleet-card').forEach(card=>card.hidden=!card.dataset.search.includes(query));}});
document.addEventListener('change',async e=>{try{if(e.target.id==='server-picker'){const next=e.target.value;if(!await discard()){e.target.value=selected;return;}selected=next;dirty=false;configs=null;steamOutput='';steamSession=null;if(view==='console'&&consoleTab==='steam')await refreshSteam();if(view==='configuration'&&configTab!=='basics')await getConfigs();render();}
  if(e.target.id==='language-select'){const next=e.target.value;if(!await discard()){e.target.value=currentLanguage;return;}await api('settings',{language:next});dirty=false;await refresh();}
  if(e.target.id==='ini-file'){const next=e.target.value;if(!await discard()){e.target.value=file;return;}file=next;dirty=false;render();}
  if(e.target.name==='removeServerPassword')e.target.form.elements.serverPassword.disabled=e.target.checked;
  if(e.target.id==='catalog-group')filterCatalog();if(e.target.id==='steam-follow')steamFollow=e.target.checked;
}catch(err){toast(errorMessage(err),true);}});
function filterCatalog(){const q=$('#catalog-search').value.toLowerCase(),group=$('#catalog-group').value;$$('.catalog-field').forEach(el=>el.hidden=!el.dataset.key.includes(q)||(group!=='all'&&el.dataset.group!==group));}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
load().then(()=>{render();window.asa.ready();}).catch(err=>{$('#app').textContent=errorMessage(err);});
setInterval(async()=>{if(dirty||$('#dialog').open||document.activeElement?.matches('input,textarea,select'))return;try{if(view==='console'&&consoleTab==='steam')await load();else await refresh();}catch(err){toast(errorMessage(err),true);}},12000);
